{{ config(materialized='table') }}

with
quarantined as (
    select
        product_code,
        order_line_record_id,
        order_id,
        order_line_source_product_id,
        line_number,
        line_quantity,
        line_unit_price,
        line_revenue,
        line_currency,
        line_order_date,
        order_line_source_system,
        product_name,
        product_status,
        product_record_id,
        product_source_id,
        product_source_system,
        product_brand,
        product_category,
        product_list_price,
        product_currency,
        product_as_of_date,
        violation_00
    from {{ ref("ecommerce__order_line_product__checked") }}
),
violations as (
    select
        'product_code_not_null' as rule_name,
        product_code,
        order_line_record_id,
        order_id,
        order_line_source_product_id,
        line_number,
        line_quantity,
        line_unit_price,
        line_revenue,
        line_currency,
        line_order_date,
        order_line_source_system,
        product_name,
        product_status,
        product_record_id,
        product_source_id,
        product_source_system,
        product_brand,
        product_category,
        product_list_price,
        product_currency,
        product_as_of_date
    from quarantined
    where violation_00
)

select
    rule_name,
    product_code,
    order_line_record_id,
    order_id,
    order_line_source_product_id,
    line_number,
    line_quantity,
    line_unit_price,
    line_revenue,
    line_currency,
    line_order_date,
    order_line_source_system,
    product_name,
    product_status,
    product_record_id,
    product_source_id,
    product_source_system,
    product_brand,
    product_category,
    product_list_price,
    product_currency,
    product_as_of_date
from violations
